select jsonb_build_object('team',(select jsonb_agg(jsonb_build_object('id',id,'role',team_role,'removed',removed_at is not null,'linked',user_id is not null,'version',row_version,'complete',nullif(btrim(member_name),'') is not null and nullif(btrim(actual_job_title),'') is not null)) from public.audit_team_members where audit_id='3c0c9f1a-fdfb-42f9-8f2c-ce92c6ac474b'),'lead_matches_header',exists(select 1 from public.audits a join public.audit_team_members m on m.audit_id=a.id and m.removed_at is null and m.team_role='lead' where a.id='3c0c9f1a-fdfb-42f9-8f2c-ce92c6ac474b' and m.user_id=a.lead_auditor_id and m.member_name=a.evaluator_name)) verification;
